TASK_NAME = "sweep_readiness"
TASK_PATH = "readiness.tasks.sweep_readiness"


def seed_periodic_task(apps, schema_editor):
    CrontabSchedule = apps.get_model("django_celery_beat", "CrontabSchedule")
    PeriodicTask = apps.get_model("django_celery_beat", "PeriodicTask")

    crontab, _ = CrontabSchedule.objects.get_or_create(
        minute="8,23,38,53",
        hour="*",
        day_of_week="*",
        day_of_month="*",
        month_of_year="*",
        timezone=getattr(settings, "TIME_ZONE", "UTC"),
    )
    task, created = PeriodicTask.objects.get_or_create(
        name=TASK_NAME,
        defaults={
            "task": TASK_PATH,
            "crontab": crontab,
            "enabled": True,
            "description": (
                "Refresh each athlete's readiness and personal Order of the Day, "
                "then send opted-in morning pushes that are outside quiet hours."
            ),
        },
    )
    changed = []
    if task.task != TASK_PATH:
        task.task = TASK_PATH
        changed.append("task")
    if task.crontab_id != crontab.id:
        task.crontab = crontab
        changed.append("crontab")
    if not task.enabled:
        task.enabled = True
        changed.append("enabled")
    if changed and not created:
        task.save()


def remove_periodic_task(apps, schema_editor):
    PeriodicTask = apps.get_model("django_celery_beat", "PeriodicTask")
    PeriodicTask.objects.filter(name=TASK_NAME).delete()


